function readAsBase64(blob) {
    return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const result = reader.result;
            // 去掉 "data:...;base64," 前缀
            const b64 = result.split(',')[1] || result;
            resolve(b64);
        };
        reader.readAsDataURL(blob);
    });
}

