// ===== 聊天消息渲染 =====
function renderMessages(uuid) {
    chatMessages.innerHTML = '';
    const contact = contacts.get(uuid);
    if (!contact || !contact.messages) return;

    const items = contact.messages;
    for (const m of items) {
        const div = document.createElement('div');

        // 文件消息
        if (m.type === 'file') {
            renderFileBubble(div, m);
            chatMessages.appendChild(div);
            continue;
        }

        // 系统消息
        if (m.from === 'system') {
            div.className = 'msg system';
            div.textContent = m.content;
            chatMessages.appendChild(div);
            continue;
        }

        // 普通文本消息
        if (m.from === 'me') {
            div.className = 'msg sent';
            const statusIcon = m.status === 'sending' ? '🕒' :
                               m.status === 'failed' ? '⚠️' : '✓';
            const statusClass = m.status === 'sending' ? 'status-sending' :
                                m.status === 'failed' ? 'status-failed' : 'status-sent';
            div.innerHTML = `${esc(m.content)}<div class="time">${fmtTime(m.timestamp)} <span class="status ${statusClass}">${statusIcon}</span></div>`;
        } else {
            div.className = 'msg received';
            div.innerHTML = `${esc(m.content)}<div class="time">${fmtTime(m.timestamp)}</div>`;
        }
        chatMessages.appendChild(div);
    }
    chatMessages.scrollTop = chatMessages.scrollHeight;
}

/** 渲染文件消息气泡 */
function renderFileBubble(container, msg) {
    const isSent = msg.direction === 'send';
    container.className = `msg file-msg ${isSent ? 'sent' : 'received'}`;

    let statusText = '';
    if (msg.status === 'waiting') statusText = '等待对方确认...';
    else if (msg.status === 'uploading') statusText = `发送中 ${msg.progress || 0}%`;
    else if (msg.status === 'downloading') statusText = `接收中 ${msg.progress || 0}%`;
    else if (msg.status === 'complete') statusText = isSent ? '发送完成 ✓' : '接收完成 ✓';
    else if (msg.status === 'failed') statusText = '传输失败 ✗';
    else if (msg.status === 'cancelled') statusText = '已取消';

    const showProgress = msg.status === 'uploading' || msg.status === 'downloading' || msg.status === 'waiting';
    const showOpen = msg.status === 'complete' && !isSent;

    let actionHtml = '';
    if (showOpen) {
        actionHtml = `<button class="btn-open-file" onclick="openDownloadedFile('${escAttr(msg.file_name)}')">📂 打开文件</button>`;
    }

    container.innerHTML = `
        <div class="file-card">
            <div class="file-icon">📄</div>
            <div class="file-info">
                <div class="file-name">${esc(msg.file_name)}</div>
                <div class="file-size">${formatSize(msg.file_size)}</div>
                ${showProgress ? `
                <div class="file-progress-bar">
                    <div class="file-progress-fill" style="width:${msg.progress || 0}%"></div>
                </div>` : ''}
                <div class="file-status">${statusText}</div>
                ${actionHtml}
            </div>
        </div>
    `;
}

