    // 用实时在线列表判断状态，与点击行为保持一致
    const isOnline = onlinePeers.has(uuid);
    const dotClass = isOnline ? 'online' : 'offline';
    const statusText = isOnline ? '' : ' (离线)';
    div.innerHTML = `
        <span class="dot ${dotClass}"></span>
        <div class="info">
            <div class="name">${esc(contact.name)}${statusText}</div>
