1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 *   pendingFileTransfers - 待处理的文件上传 {transferId: {file, uuid, ...}}
13	 */
14	
15	// ===== 全局状态 =====
16	let myInfo = null;
17	let onlinePeers = new Map();
18	let contacts = new Map();
19	let pendingRequests = new Map();
20	let activeChats = new Map();         // uuid → WebSocket（主动发起方有值）
21	let connectedPeers = new Set();      // 连接已确认的 peer uuid（双方向都追踪，含接收方）
22	let currentChat = null;
23	let pendingMessages = new Map();
24	let controlWs = null;
25	let reconnectTimer = null;
26	let reconnectAttempts = 0;
27	
28	// 文件传输状态
29	let pendingFileTransfers = {};
30	
31	// ===== DOM 引用 =====
32	const $ = (id) => document.getElementById(id);
33	const onlineList = $('online-list');
34	const onlineCount = $('online-count');
35	const pendingList = $('pending-list');
36	const pendingCount = $('pending-count');
37	const panelPending = $('panel-pending');
38	const contactsList = $('contacts-list');
39	const contactsCount = $('contacts-count');
40	const chatPlaceholder = $('chat-placeholder');
41	const chatContainer = $('chat-container');
42	const chatPeerName = $('chat-peer-name');
43	const chatPeerStatus = $('chat-peer-status');
44	const chatMessages = $('chat-messages');
45	const msgInput = $('msg-input');
46	const btnSend = $('btn-send');
47	const btnSendFile = $('btn-send-file');
48	const fileInput = $('file-input');
49	const btnCloseChat = $('btn-close-chat');
