61	async function init() {
62	    await connectControl();
63	    bindEvents();
64	    startPolling();
65	}
66	
67	/** 连接控制 WebSocket */
68	async function connectControl() {
69	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
70	    const url = `${protocol}//${location.host}/ws/control`;
71	
72	    return new Promise((resolve) => {
73	        controlWs = new WebSocket(url);
74	
75	        controlWs.onopen = () => {
76	            reconnectAttempts = 0;
77	            console.log('[Control] 已连接');
78	        };
79	
80	        controlWs.onmessage = (e) => {
81	            const msg = JSON.parse(e.data);
82	            handleControlMessage(msg);
83	            if (msg.type === 'init') resolve();
84	        };
85	
86	        controlWs.onclose = () => {
87	            console.log('[Control] 断开，尝试重连...');
88	            scheduleReconnect();
89	        };
90	
91	        controlWs.onerror = () => {};
92	    });
93	}
94	
95	/** 控制 WS 断开后指数退避重连 */
96	function scheduleReconnect() {
97	    if (reconnectTimer) return;
98	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
99	    const jitter = delay * (0.8 + Math.random() * 0.4);
100	    reconnectAttempts++;
101	    reconnectTimer = setTimeout(async () => {
102	        reconnectTimer = null;
103	        await connectControl();
104	    }, jitter);
105	}
106	
107	// ===== 事件绑定 =====
108	function bindEvents() {
109	    btnScan.addEventListener('click', () => fetchPeers());
110	    btnEditName.addEventListener('click', showEditNameModal);
111	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
112	    $('btn-modal-save').addEventListener('click', saveName);
113	    modalNameInput.addEventListener('keydown', (e) => {
114	        if (e.key === 'Enter') saveName();
115	    });
116	    btnSend.addEventListener('click', sendCurrentMessage);
117	    msgInput.addEventListener('keydown', (e) => {
118	        if (e.key === 'Enter') sendCurrentMessage();
119	    });
120	    btnSendFile.addEventListener('click', () => fileInput.click());
121	    fileInput.addEventListener('change', onFileSelected);
122	    btnCloseChat.addEventListener('click', closeCurrentChat);
123	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
124	
125	    // 手动连接：toggle 展开/收起
126	    const btnManualConnect = $('btn-manual-connect');
127	    const manualIpInput = $('manual-ip-input');
128	
129	    btnManualConnect.addEventListener('click', () => {
130	        const raw = manualIpInput.value.trim();
131	        if (!raw) return;
132	        let [ip, port] = raw.split(':');
133	        port = parseInt(port) || 50002;
134	        connectByIp(ip, port);
135	        manualIpInput.value = '';
136	        toggleManualConnect(); // 收起
137	    });
138	    manualIpInput.addEventListener('keydown', (e) => {
139	        if (e.key === 'Enter') btnManualConnect.click();
140	    });
141	}
142	
143	/** 展开/收起手动连接输入行（内联 onclick 和 JS 均可调用） */
144	function toggleManualConnect() {
145	    const row = $('manual-connect-row');
146	    const btn = $('btn-toggle-manual');
147	    if (!row || !btn) return;
148	    const visible = row.style.display !== 'none';
149	    row.style.display = visible ? 'none' : '';
150	    btn.textContent = visible ? '➕' : '✖';
151	    if (!visible) $('manual-ip-input').focus();
152	}
