383	function handleTransferProgress(msg) {
384	    // 接收方：更新文件消息进度
385	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
386	    if (fileMsg && msg.total_bytes > 0) {
387	        fileMsg.progress = Math.round(msg.received_bytes / msg.total_bytes * 100);
388	        if (currentChat) renderMessages(currentChat);
389	    }
390	}
