392	function handleTransferComplete(msg) {
393	    // 接收方：传输完成
394	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
395	    if (fileMsg) {
396	        fileMsg.status = msg.verified ? 'complete' : 'failed';
397	        fileMsg.progress = 100;
398	        saveFileMessage(currentChat, fileMsg);
399	        if (currentChat) renderMessages(currentChat);
400	    }
401	    if (msg.verified) {
402	        showToast(`文件接收完成: ${msg.file_name}`);
403	    } else {
404	        showToast(`文件校验失败: ${msg.file_name}`);
405	    }
406	}
