408	function handleTransferCancelled(msg) {
409	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
410	    if (fileMsg) {
411	        fileMsg.status = 'cancelled';
412	        saveFileMessage(currentChat, fileMsg);
413	        if (currentChat) renderMessages(currentChat);
414	    }
415	    // 清理上传方状态
416	    if (pendingFileTransfers[msg.transfer_id]) {
417	        delete pendingFileTransfers[msg.transfer_id];
418	    }
419	    showToast('文件传输已取消');
420	}
