606	// ===== 连接对端 / 打开聊天 =====
607	
608	/**
609	 * 主动发起与对端的 WebSocket 连接。
610	 * 流程: 连接 ws://peer_ip:ws_port/ws/chat → 发 connect_request（带 token）→ 等 connect_accepted
611	 */
612	async function connectToPeer(uuid, name, ip) {
613	    // 如果已有活跃连接，直接打开聊天
614	    if (activeChats.has(uuid)) {
615	        openChat(uuid);
616	        return;
617	    }
618	
619	    // 获取对端 ws_port（从在线节点列表）
620	    const peer = onlinePeers.get(uuid);
621	    if (!peer) {
622	        showToast('对方不在线');
623	        return;
624	    }
625	
626	    openChat(uuid); // 先打开聊天窗口，显示"连接中..."
627	
628	    // 连接前先刷新自己的 token（token 每3秒更新，避免用过期的）
629	    try {
630	        const resp = await fetch('/api/me');
631	        const me = await resp.json();
632	        myInfo.token = me.token;
633	    } catch (e) { /* 刷新失败则用现有 token */ }
634	
635	    try {
636	        const peerPort = peer.ws_port || 50002;
637	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
638	        const ws = new WebSocket(wsUrl);
639	
640	        ws.onopen = () => {
641	            // 发送连接请求，带上自己的 token 给对方后端验证
642	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
643	            ws.send(JSON.stringify({
644	                type: 'connect_request',
645	                uuid: myInfo.uuid,
646	                name: myInfo.name,
647	                token: myInfo.token,
648	                ip: myInfo.ip,
649	                ws_port: myInfo.ws_port,
650	            }));
651	        };
652	
653	        ws.onmessage = (e) => {
654	            const msg = JSON.parse(e.data);
655	            if (msg.type === 'connect_accepted') {
656	                activeChats.set(uuid, ws);
657	                connectedPeers.add(uuid);
658	                setupPeerMessageHandler(uuid, ws);
659	                addSystemMessage(uuid, '连接已建立');
660	                updateChatHeaderStatus();
661	                renderOnlineList();
662	                renderContactsList();
663	                // 通知自己后端保存联系人（对方后端已保存，自己后端也需要记录）
664	                controlWs.send(JSON.stringify({
665	                    type: 'save_contact',
666	                    uuid: uuid,
667	                    name: name,
668	                    ip: ip,
669	                    ws_port: peer.ws_port || 50002,
670	                }));
671	            } else if (msg.type === 'connect_rejected') {
672	                ws.close();
673	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
674	                addSystemMessage(uuid, reason);
675	                showToast(reason);
676	            }
677	        };
678	
679	        ws.onclose = () => {
680	            activeChats.delete(uuid);
681	            connectedPeers.delete(uuid);
682	            renderOnlineList();
683	            renderContactsList();
684	            if (currentChat === uuid) {
685	                addSystemMessage(uuid, '连接已断开');
686	                updateChatHeaderStatus();
687	            }
688	        };
689	
690	        ws.onerror = () => {
691	            activeChats.delete(uuid);
692	            addSystemMessage(uuid, '连接失败，请检查网络');
693	            showToast('连接失败');
694	            ws.close();
695	        };
696	
697	    } catch (e) {
698	        addSystemMessage(uuid, `连接失败: ${e.message}`);
699	    }
700	}
701	
702	/**
703	 * 手动输入 IP 连接（跨子网场景）。
704	 * 与 connectToPeer 的区别：不需要对方在 onlinePeers 中（UDP 广播到不了）。
705	 */
706	async function connectByIp(ip, port) {
707	    port = port || 50002;
708	    // 生成临时 UUID（等 connect_accepted 时会替换为真实 UUID）
709	    const tempUuid = 'manual_' + ip + '_' + port;
710	
711	    if (activeChats.has(tempUuid)) {
712	        showToast('已在连接中');
713	        return;
714	    }
715	
716	    // 防止自连：不能连自己的 IP:端口
717	    if (ip === myInfo.ip && port === myInfo.ws_port) {
718	        showToast('不能连接到自己的实例');
719	        return;
720	    }
721	
722	    openChat(tempUuid);
723	    addSystemMessage(tempUuid, `正在连接 ${ip}:${port}...`);
724	
725	    // 连接前刷新自己的 token
726	    try {
727	        const resp = await fetch('/api/me');
728	        const me = await resp.json();
729	        myInfo.token = me.token;
730	    } catch (e) { /* ignore */ }
731	
732	    try {
