1105	/**
1106	 * 发送文件：添加文件消息气泡 → 发 file_request → 等对方响应后自动开始上传。
1107	 */
1108	async function sendFile(uuid, file) {
1109	    const CHUNK_SIZE = 64 * 1024; // 64KB
1110	    const transferId = 't_' + myInfo.uuid + '_' + Date.now();
1111	    const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
1112	
1113	    // 在聊天中插入文件消息气泡（初始状态：等待确认）
1114	    const contact = contacts.get(uuid);
1115	    if (!contact.messages) contact.messages = [];
1116	    const fileMsg = {
1117	        from: 'me',
1118	        type: 'file',
1119	        msg_id: 'f_' + transferId,
1120	        timestamp: new Date().toISOString(),
1121	        file_name: file.name,
1122	        file_size: file.size,
1123	        transfer_id: transferId,
1124	        direction: 'send',
1125	        status: 'waiting',
1126	        progress: 0,
1127	    };
1128	    contact.messages.push(fileMsg);
1129	    renderMessages(uuid);
1130	
1131	    // 持久化文件消息
1132	    saveFileMessage(uuid, fileMsg);
1133	
1134	    // 注册待处理传输
1135	    pendingFileTransfers[transferId] = {
1136	        file: file,
1137	        uuid: uuid,
1138	        totalChunks: totalChunks,
1139	        CHUNK_SIZE: CHUNK_SIZE,
1140	        transferId: transferId,
1141	        currentChunk: 0,
1142	        started: false,
1143	    };
1144	
1145	    const fileRequestMsg = {
1146	        transfer_id: transferId,
1147	        file_name: file.name,
1148	        file_size: file.size,
1149	        chunk_size: CHUNK_SIZE,
1150	        total_chunks: totalChunks,
1151	        resume: false,
1152	    };
1153	
1154	    // 优先走直连 chat WS；没有则回退到 control WS 转发
1155	    const ws = activeChats.get(uuid);
1156	    if (ws && ws.readyState === WebSocket.OPEN) {
1157	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
1158	    } else {
1159	        // 回退路径：通过 control WS → 自己后端 → 转发给对端
1160	        controlWs.send(JSON.stringify({
1161	            type: 'file_request',
1162	            to_uuid: uuid,
1163	            ...fileRequestMsg,
1164	        }));
1165	    }
1166	}
